function pacificAtlantic(heights: number[][]): number[][] {
  const m = heights.length
  const n = heights[0].length
  const flood = (starts: number[][]) => {
    const seen = Array.from({ length: m }, () => new Array<boolean>(n).fill(false))
    const stack = [...starts]
    for (const [r, c] of starts) seen[r][c] = true
    while (stack.length) {
      const [r, c] = stack.pop()!
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr
        const nc = c + dc
        if (nr < 0 || nc < 0 || nr >= m || nc >= n || seen[nr][nc]) continue
        if (heights[nr][nc] < heights[r][c]) continue
        seen[nr][nc] = true
        stack.push([nr, nc])
      }
    }
    return seen
  }
  const pac: number[][] = []
  const atl: number[][] = []
  for (let r = 0; r < m; r++) { pac.push([r, 0]); atl.push([r, n - 1]) }
  for (let c = 0; c < n; c++) { pac.push([0, c]); atl.push([m - 1, c]) }
  const p = flood(pac)
  const a = flood(atl)
  const result: number[][] = []
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (p[r][c] && a[r][c]) result.push([r, c])
  return result
}
